442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442** (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043e `find / -name 'track.md'`). \\u042d\\u0442\\u043e \\u0441\\u043f\\u0440\\u0430\\u0432\\u043e\\u0447\\u043d\\u0430\\u044f \\u0430\\u043d\\u043d\\u043e\\u0442\\u0430\\u0446\\u0438\\u044f, \\u0430 \\u043d\\u0435 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442.\\n- **\\u0420\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u044f BAdam \\u043d\\u0435\\u0442** (\\u043d\\u0435\\u0442 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432, \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u043e\\u0432, README), \\u0441\\u0442\\u0430\\u0442\\u0435\\u0439/\\u0437\\u0430\\u043c\\u0435\\u0442\\u043e\\u043a \\u043d\\u0435\\u0442, \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0435\\u0442.\\n- **\\u0421\\u0440\\u0435\\u0434\\u0430**: Python 3.14.4 (system), **\\u043d\\u0435\\u0442 numpy / scipy / torch / transformers**, \\u0441\\u0435\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430 (pip-install \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u0435\\u043d), GPU \\u043d\\u0435\\u0442, 224 \\u044f\\u0434\\u0440\\u0430, \\u043d\\u043e \\u0432\\u0441\\u0435\\u0433\\u043e **~2 \\u0413\\u0411 RAM**.\\n\\n**\\u0421\\u043b\\u0435\\u0434\\u0441\\u0442\\u0432\\u0438\\u0435 \\u0434\\u043b\\u044f \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430**: \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442 \\u0434\\u043e\\u043b\\u0436\\u0435\\u043d \\u0431\\u044b\\u0442\\u044c \\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c \\u043d\\u0430 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c stdlib-Python. \\u0417\\u043d\\u0430\\u0447\\u0438\\u0442: \\u043a\\u0440\\u043e\\u0448\\u0435\\u0447\\u043d\\u044b\\u0439 \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440, \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0432\\u0440\\u0443\\u0447\\u043d\\u0443\\u044e; \\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 Adam, BAdam (block-coordinate Adam), Jacobi-SVD; \\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430 \\u0432\\u043c\\u0435\\u0441\\u0442\\u043e \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u0430. \\u0412\\u0441\\u0451 \\u044d\\u0442\\u043e \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c\\u043e \\u043f\\u0440\\u0438 \\u043c\\u0430\\u043b\\u044b\\u0445 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u043d\\u043e\\u0441\\u0442\\u044f\\u0445 (d_model \\u2264 32, 1\\u20132 \\u0441\\u043b\\u043e\\u044f, SVD \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446 \\u2264 64\\u00d764 \\u0447\\u0438\\u0441\\u0442\\u044b\\u043c Python \\u2014 \\u043c\\u0435\\u0434\\u043b\\u0435\\u043d\\u043d\\u043e, \\u043d\\u043e \\u043f\\u0440\\u0438\\u0435\\u043c\\u043b\\u0435\\u043c\\u043e \\u0437\\u0430 \\u0440\\u0430\\u0437\\u0443\\u043c\\u043d\\u043e\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f; \\u043f\\u0440\\u0438 \\u0436\\u0435\\u043b\\u0430\\u043d\\u0438\\u0438 \\u043c\\u043e\\u0436\\u043d\\u043e \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c, \\u0440\\u0430\\u0437\\u0440\\u0435\\u0448\\u0435\\u043d\\u0430 \\u043b\\u0438 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430 numpy \\u0438\\u0437 \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043a\\u0435\\u0448\\u0430 \\u2014 \\u043f\\u043e\\u043a\\u0430 \\u0441\\u0447\\u0438\\u0442\\u0430\\u044e, \\u0447\\u0442\\u043e \\u043d\\u0435\\u0442).\\n\\n## 2. \\u041f\\u043e\\u043d\\u044f\\u0442\\u0438\\u0439\\u043d\\u044b\\u0439 \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441 (\\u0447\\u0442\\u043e \\u043e\\u0442\\u043a\\u0443\\u0434\\u0430 \\u0431\\u0435\\u0440\\u0451\\u0442\\u0441\\u044f, \\u0447\\u0442\\u043e \\u2014 \\u043c\\u043e\\u0451 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435)\\n\\n**\\\"Learning perturbation\\\"** \\u2014 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u044f\\u044e \\u043a\\u0430\\u043a **\\u0444\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0435\\u0441\\u043e\\u0432** \\u0394W = W_t \\u2212 W_t\\u22121 (\\u0438\\u043b\\u0438 \\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u0438\\u0432\\u043d\\u043e\\u0435 \\u0394W \\u0437\\u0430 \\u043e\\u043a\\u043d\\u043e \\u0438\\u0437 k \\u0448\\u0430\\u0433\\u043e\\u0432) \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0432\\u0435\\u0441\\u043e\\u0432\\u043e\\u0433\\u043e \\u043c\\u043e\\u0434\\u0443\\u043b\\u044f. \\u042d\\u0442\\u043e \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u0430\\u044f \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u00ab\\u0432\\u043e\\u0437\\u043c\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f\\u00bb \\u0432 \\u043b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u0435 \\u043f\\u043e \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430\\u043c \\u0432\\u0435\\u0441\\u043e\\u0432 (heavy-tailed self-regularization, Martin & Mahoney 2018\\u20132021, \\u0433\\u0434\\u0435 \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u044e\\u0442 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u044b \\u0441\\u0438\\u043d\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u044b\\u0445 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0439 \\u0432\\u0435\\u0441\\u043e\\u0432; \\u0432 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0435 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u043e\\u0432 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u044b \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0439 \\u0394W \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043b\\u0438\\u0441\\u044c \\u0432 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0445 \\u043f\\u043e SVD/low-rank \\u0430\\u0434\\u0430\\u043f\\u0442\\u0435\\u0440\\u0430\\u043c \\u0438 \\u00abspectral bias\\u00bb). **\\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435**: \\u0431\\u0435\\u0440\\u0443 \\u0394W \\u043a\\u0430\\u043a \\u043f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u0443\\u044e \\u0432\\u0435\\u043b\\u0438\\u0447\\u0438\\u043d\\u0443; \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u0443 (\\u043f\\u0441\\u0435\\u0432\\u0434\\u043e\\u0433\\u0440\\u0430\\u0434\\u0438\\u0435\\u043d\\u0442 m\\u0302_t = m/(1\\u2212\\u03b2\\u2081\\u1d57), \\u0442.\\u0435. \\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442 Adam) \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e \\u043a\\u0430\\u043a \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u0443\\u044e \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0443, \\u0442.\\u043a. \\u0443 BAdam \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442\\u044b \\u0432\\u0435\\u0434\\u0443\\u0442\\u0441\\u044f \\u0431\\u043b\\u043e\\u043a-\\u043a\\u043e\\u043e\\u0440\\u0434\\u0438\\u043d\\u0430\\u0442\\u043d\\u043e \\u0438 \\u0438\\u0445 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440 \\u2014 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0442\\u0435\\u0440\\u0435\\u0441\\u043d\\u044b\\u0439 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b. \\u0415\\u0441\\u043b\\u0438 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c \\u0441\\u0447\\u0438\\u0442\\u0430\\u0435\\u0442 \\\"perturbation\\\" \\u0438\\u043d\\u0430\\u0447\\u0435 (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, \\u0432 \\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0430\\u0445 \\u0441\\u0430\\u043c\\u043e\\u0439 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 BAdam) \\u2014 \\u044d\\u0442\\u043e \\u043d\\u0443\\u0436\\u043d\\u043e \\u0443\\u0442\\u043e\\u0447\\u043d\\u0438\\u0442\\u044c.\\n\\n**\\u0422\\u044f\\u0436\\u0451\\u043b\\u044b\\u0439 \\u0445\\u0432\\u043e\\u0441\\u0442**: \\u043f\\u043e\\u0434\\u0433\\u043e\\u043d\\u043a\\u0430 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u043a\\u043e\\u043d\\u0430 p(\\u03c3) \\u221d \\u03c3^(\\u2212\\u03b1) \\u043a \\u0432\\u0435\\u0440\\u0445\\u043d\\u0435\\u043c\\u0443 \\u0443\\u0447\\u0430\\u0441\\u0442\\u043a\\u0443 \\u043e\\u0442\\u0441\\u043e\\u0440\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430 \\u0441\\u0438\\u043d\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u044b\\u0445 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0439 (\\u041a\\u043bauset\\u2013Shalizi\\u2013Newman CLAUSET method: \\u043f\\u043e\\u0434\\u0431\\u043e\\u0440 x_min \\u0438 \\u03b1 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u043c \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u0430\\u0432\\u0434\\u043e\\u043f\\u043e\\u0434\\u043e\\u0431\\u0438\\u044f, \\u043f\\u043b\\u044e\\u0441 \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0438\\u044f \\u044d\\u043a\\u0441\\u043f\\u043e\\u043d\\u0435\\u043d\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e/\\u043b\\u043e\\u0433\\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043a\\u043e\\u043d\\u043a\\u0443\\u0440\\u0435\\u043d\\u0442\\u0430 \\u2014 CSN 2009). \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430: \\u03b1\\u0302 (\\u043c\\u0435\\u043d\\u044c\\u0448\\u0435 \\u2192 \\u0442\\u044f\\u0436\\u0435\\u043b\\u0435\\u0435 \\u0445\\u0432\\u043e\\u0441\\u0442) \\u0438 \\u0434\\u043e\\u043b\\u044f \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430, \\u043f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0430\\u044f \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u044b\\u043c \\u0443\\u0447\\u0430\\u0441\\u0442\\u043a\\u043e\\u043c. \\u042d\\u0442\\u043e \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u0430\\u044f \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u043b\\u043e\\u0433\\u0438\\u044f HT-SR. **\\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435**: \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430\\u044f \\u043f\\u0440\\u043e\\u0441\\u0442\\u0430\\u044f \\u0441\\u0432\\u043e\\u0434\\u043d\\u0430\\u044f \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u2014 \\u0434\\u043e\\u043b\\u044f \\u044d\\u043d\\u0435\\u0440\\u0433\\u0438\\u0438 \\u0442\\u043e\\u043f-k \\u0441\\u0438\\u043d\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u044b\\u0445 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0439.\\n\\n**\\u042d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 \\u0440\\u0430\\u043d\\u0433**: \\u0434\\u0432\\u0430 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u0445 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f (\\u043e\\u0431\\u0430 \\u0438\\u0437 \\u043b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u044b, \\u043d\\u0435 \\u043c\\u043e\\u0438):\\n- **Participation ratio**: PR = (\\u03a3\\u03c3\\u1d62)\\u00b2 / \\u03a3\\u03c3\\u1d62\\u00b2 (Roy & Vetterli 2007; \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u0442\\u0441\\u044f \\u0432 \\u043d\\u0435\\u0439\\u0440\\u043e\\u0441\\u0435\\u0442\\u0435\\u0432\\u043e\\u043c \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0435, \\u043d\\u0430\\u043f\\u0440. Gao et al.).\\n- **Stable rank**: srank = \\u2016W\\u2016_F\\u00b2 / \\u03c3_max\\u00b2 (Rudelson\\u2013Vershynin; \\u0448\\u0438\\u0440\\u043e\\u043a\\u043e \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043a \\u0432\\u0435\\u0441\\u0430\\u043c \\u0441\\u0435\\u0442\\u0435\\u0439).\\n\\n\\u0421\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\\"comparable to Adam\\\" \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u044e: (a) \\u0440\\u0430\\u0432\\u0435\\u043d\\u0441\\u0442\\u0432\\u043e/\\u0431\\u043b\\u0438\\u0437\\u043e\\u0441\\u0442\\u044c \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u043d\\u044b\\u0445 \\u03b1\\u0302, PR, srank \\u043f\\u043e \\u043c\\u043e\\u0434\\u0443\\u043b\\u044f\\u043c \\u0438 \\u0448\\u0430\\u0433\\u0430\\u043c \\u0441 \\u0434\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u043c\\u0438 \\u0438\\u043d\\u0442\\u0435\\u0440\\u0432\\u0430\\u043b\\u0430\\u043c\\u0438 \\u043f\\u043e seed'\\u0430\\u043c; (b) \\u0442\\u0435\\u0441\\u0442 \\u044d\\u043a\\u0432\\u0438\\u0432\\u0430\\u043b\\u0435\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 (TOST) \\u0438\\u043b\\u0438 \\u043f\\u0435\\u0440\\u0435\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 CI \\u0441 \\u0437\\u0430\\u0440\\u0430\\u043d\\u0435\\u0435 \\u0437\\u0430\\u0434\\u0430\\u043d\\u043d\\u044b\\u043c \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u043c \\u043f\\u043e\\u0440\\u043e\\u0433\\u043e\\u043c \\u0394.\\n\\n## 3. \\u041a\\u0430\\u0440\\u043a\\u0430\\u0441 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 (\\u043d\\u0430\\u0431\\u0440\\u043e\\u0441\\u043e\\u043a, \\u0431\\u0435\\u0437 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430)\\n\\n- **\\u041e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u044b**: (1) \\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 Adam (\\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c), (2) BAdam \\u2014 block-coordinate Adam: \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b \\u0440\\u0430\\u0437\\u0431\\u0438\\u0442\\u044b \\u043d\\u0430 \\u0431\\u043b\\u043e\\u043a\\u0438 (\\u043f\\u043e \\u043e\\u0434\\u043d\\u043e\\u043c\\u0443 \\u0432\\u0435\\u0441\\u043e\\u0432\\u043e\\u043c\\u0443 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044e \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0430 \\u0437\\u0430 \\u0431\\u043b\\u043e\\u043a), \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c \\u0448\\u0430\\u0433\\u0435 Adam-\\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f **\\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043a \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u043c\\u0443 \\u0431\\u043b\\u043e\\u043a\\u0443**, \\u0431\\u043b\\u043e\\u043a\\u0438 \\u0446\\u0438\\u043a\\u043b\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043e\\u0431\\u0445\\u043e\\u0434\\u044f\\u0442\\u0441\\u044f (\\u0441\\u0445\\u0435\\u043c\\u0430 \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 BAdam: arXiv 2404.18182 \\u2014 *\\u044d\\u0442\\u043e \\u043c\\u043e\\u0451 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043e \\u0434\\u0435\\u0442\\u0430\\u043b\\u044f\\u0445, \\u0442.\\u043a. \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u043d\\u0435\\u0442*). \\u041e\\u043f\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e (3) SGD \\u043a\\u0430\\u043a sanity-check \\\"\\u0431\\u043e\\u043b\\u0435\\u0435 \\u0441\\u043b\\u0430\\u0431\\u043e\\u0433\\u043e\\\" \\u0432\\u043e\\u0437\\u043c\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043f\\u043e\\u043a\\u0430\\u0437\\u0430\\u0442\\u044c, \\u0447\\u0442\\u043e \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u0432\\u043e\\u043e\\u0431\\u0449\\u0435 \\u0440\\u0430\\u0437\\u043b\\u0438\\u0447\\u0430\\u044e\\u0442 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u044b.\\n- **\\u041c\\u043e\\u0434\\u0435\\u043b\\u044c**: \\u043a\\u0440\\u043e\\u0448\\u0435\\u0447\\u043d\\u044b\\u0439 \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440 \\u043d\\u0430 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c Python: 1\\u20132 \\u0441\\u043b\\u043e\\u044f, d_model 16\\u201332, 2\\u20134 \\u0433\\u043e\\u043b\\u043e\\u0432\\u044b, QKVO-\\u043f\\u0440\\u043e\\u0435\\u043a\\u0446\\u0438\\u0438, MLP (d_ff = 4d), embedding + tied head. \\u0417\\u0430\\u0434\\u0430\\u0447\\u0430 \\u2014 \\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, \\u043f\\u0440\\u0435\\u0434\\u0441\\u043a\\u0430\\u0437\\u0430\\u043d\\u0438\\u0435 \\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0435\\u0433\\u043e \\u0441\\u0438\\u043c\\u0432\\u043e\\u043b\\u0430 \\u0432 \\u043c\\u0430\\u043b\\u043e\\u043c \\u043c\\u0430\\u0440\\u043a\\u043e\\u0432\\u0441\\u043a\\u043e\\u043c/\\u043a\\u043e\\u043f\\u0438\\u0440\\u0443\\u044e\\u0449\\u0435\\u043c \\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441\\u0435) \\u2014 finetuning-\\u0444\\u0430\\u0437\\u0430 \\u0441 \\u043f\\u0440\\u0435\\u0434\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435\\u043c/\\u0438\\u043b\\u0438 \\u0438\\u043d\\u0438\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f + \\u043a\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438\\u0439 pretext, \\u0437\\u0430\\u0442\\u0435\\u043c finetune \\u0441 \\u043c\\u0430\\u043b\\u044b\\u043c lr.\\n- **\\u041c\\u043e\\u0434\\u0443\\u043b\\u0438 \\u0434\\u043b\\u044f \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430**: per-module \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u044b \\u0394W \\u0434\\u043b\\u044f: attention Q/K/V/O, MLP up/down (\\u0438\\u043b\\u0438 in/out), embedding, head. \\u042d\\u0442\\u043e \\u0434\\u0430\\u0451\\u0442 \\u043e\\u0442\\u0432\\u0435\\u0442 \\\"across various transformer modules\\\".\\n- **\\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b**: T \\u0448\\u0430\\u0433\\u043e\\u0432 (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, 300\\u2013600 finetune-\\u0448\\u0430\\u0433\\u043e\\u0432), \\u0437\\u0430\\u043c\\u0435\\u0440\\u044b \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430 \\u0394W \\u043a\\u0430\\u0436\\u0434\\u044b\\u0435 S \\u0448\\u0430\\u0433\\u043e\\u0432 (\\u043e\\u043a\\u043d\\u043e k=10\\u201320), \\u043f\\u043e \\u22655 seed'\\u0430\\u043c. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438\\u0440\\u0443\\u0435\\u043c\\u044b\\u0435 \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0435: \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0435 lr (\\u0441\\u0435\\u0442\\u043a\\u0430 2\\u20133 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0439), \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0435 init, \\u0431\\u0430\\u0442\\u0447\\u0438, \\u0447\\u0438\\u0441\\u043b\\u043e \\u0448\\u0430\\u0433\\u043e\\u0432; \\u0443 BAdam \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0432\\u0430\\u0440\\u044c\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f block schedule (\\u0446\\u0438\\u043a\\u043b\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043e\\u043a \\u2014 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d vs \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0439), \\u0442.\\u043a. \\u044d\\u0442\\u043e \\u0435\\u0434\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0430\\u044f \\u0441\\u0432\\u043e\\u0431\\u043e\\u0434\\u0430 \\u0430\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c\\u0430. Frozen-\\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435: BAdam-\\u0431\\u043b\\u043e\\u043a\\u0438 \\u0432\\u043d\\u0435 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0433\\u043e \\u0431\\u043b\\u043e\\u043a\\u0430 \\u043d\\u0435 \\u0434\\u0432\\u0438\\u0433\\u0430\\u044e\\u0442\\u0441\\u044f \\u21d2 \\u0394W \\u0432 \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c \\u043c\\u043e\\u0434\\u0443\\u043b\\u0435 \\u043d\\u0435\\u043d\\u0443\\u043b\\u0435\\u0432\\u043e\\u0439 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043d\\u0430 1/T_b \\u0448\\u0430\\u0433\\u043e\\u0432 \\u2014 \\u043d\\u0443\\u0436\\u043d\\u043e \\u0440\\u0435\\u0448\\u0438\\u0442\\u044c, \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u0435\\u043c per-step \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0431\\u043b\\u043e\\u043a\\u0430, \\u0438\\u043b\\u0438 \\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u0437\\u0430 \\u043e\\u043a\\u043d\\u043e (\\u0440\\u0435\\u043a\\u043e\\u043c\\u0435\\u043d\\u0434\\u0443\\u044e \\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u0437\\u0430 \\u043e\\u043a\\u043d\\u043e + per-active-step \\u043a\\u0430\\u043a \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 \\u0441\\u0440\\u0435\\u0437).\\n- **\\u0424\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430**: \\u043f\\u043e \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c\\u0443 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044e \\u2014 \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u044b \\u043b\\u0438 \\u0440\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f \\u03b1\\u0302/PR/srank \\u043c\\u0435\\u0436\\u0434\\u0443 BAdam \\u0438 Adam (\\u043f\\u0435\\u0440\\u0435\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 CI, TOST), \\u0438 \\u0435\\u0441\\u0442\\u044c \\u043b\\u0438 \\u0443 \\u043e\\u0431\\u043e\\u0438\\u0445 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u043e\\u0439 \\u0445\\u0432\\u043e\\u0441\\u0442 (\\u03b1\\u0302 \\u043d\\u0438\\u0436\\u0435 \\u043f\\u043e\\u0440\\u043e\\u0433\\u0430, CSN-\\u0442\\u0435\\u0441\\u0442 \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 \\u044d\\u043a\\u0441\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u044b).\\n\\n## 4. Consequential assumptions \\u0438 uncertainties\\n\\n**\\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f (\\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0442 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f):**\\n1. BAdam = block-coordinate Adam (\\u043e\\u0434\\u0438\\u043d \\u0431\\u043b\\u043e\\u043a \\u0437\\u0430 \\u0448\\u0430\\u0433, \\u043e\\u0441\\u0442\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0437\\u0430\\u043c\\u043e\\u0440\\u043e\\u0436\\u0435\\u043d\\u044b, \\u0446\\u0438\\u043a\\u043b\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043e\\u0431\\u0445\\u043e\\u0434) \\u2014 \\u043f\\u043e \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u043e \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435 arXiv 2404.18182; **\\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u0432 workspace \\u043d\\u0435\\u0442**, \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043d\\u0435\\u0447\\u0435\\u043c. \\u041a\\u0440\\u0438\\u0442\\u0438\\u0447\\u043d\\u043e: \\u0435\\u0441\\u043b\\u0438 BAdam \\u0432 \\u0446\\u0435\\u043b\\u0435\\u0432\\u043e\\u0439 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0432\\u043a\\u0435 \\u2014 \\u044d\\u0442\\u043e blockwise-\\u043f\\u0430\\u0440\\u0430\\u043b\\u043b\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440 (\\u043a\\u0430\\u043a \\u0432 Megatron/BLOOM distributed optimizer), \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f.\\n2. \\\"Learning perturbation\\\" = \\u0394W \\u0432\\u0435\\u0441\\u043e\\u0432 (\\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044e, \\u0435\\u0441\\u043b\\u0438 \\u043d\\u0443\\u0436\\u043d\\u043e).\\n3. \\u0425\\u0432\\u043e\\u0441\\u0442 \\u043c\\u0435\\u0440\\u044f\\u0435\\u043c \\u043f\\u043e \\u03c3-\\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0443 \\u0394W \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u044b\\u043c \\u0437\\u0430\\u043a\\u043e\\u043d\\u043e\\u043c (\\u03b1, CLAUSET), \\u0440\\u0430\\u043d\\u0433 \\u2014 PR \\u0438 stable rank.\\n\\n**\\u041d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0441\\u0440\\u0435\\u0434\\u044b:**\\n- \\u041d\\u0435\\u0442 numpy/torch \\u0438 \\u043d\\u0435\\u0442 \\u0441\\u0435\\u0442\\u0438 \\u21d2 \\u0432\\u0435\\u0441\\u044c \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d (SVD, Adam, BAdam, ML-\\u043f\\u043e\\u0434\\u0433\\u043e\\u043d\\u043a\\u0430 \\u03b1) \\u2014 \\u043d\\u0430 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c Python; \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435 2 \\u0413\\u0411 RAM \\u0438 \\u0441\\u043a\\u043e\\u0440\\u043e\\u0441\\u0442\\u044c \\u0447\\u0438\\u0441\\u0442\\u043e\\u0433\\u043e SVD \\u0437\\u0430\\u0434\\u0430\\u044e\\u0442 \\u043f\\u043e\\u0442\\u043e\\u043b\\u043e\\u043a \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u0430 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 (d\\u226432, 1\\u20132 \\u0441\\u043b\\u043e\\u044f). \\u042d\\u0442\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0435 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435, \\u043d\\u043e \\u0441\\u0442\\u043e\\u0438\\u0442 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0434\\u0438\\u0442\\u044c, \\u0447\\u0442\\u043e \\u043f\\u0440\\u0438\\u0435\\u043c\\u043b\\u0435\\u043c\\u043e.\\n- `track.md` \\u0443\\u043f\\u043e\\u043c\\u044f\\u043d\\u0443\\u0442, \\u043d\\u043e \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 \\u2014 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e, \\u0432 \\u043d\\u0451\\u043c \\u0431\\u044b\\u043b\\u0438 \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u043a \\u0444\\u043e\\u0440\\u043c\\u0430\\u0442\\u0443 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430.\\n- \\u042d\\u043a\\u0432\\u0438\\u0432\\u0430\\u043b\\u0435\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\\"comparable\\\" \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0437\\u0430\\u0440\\u0430\\u043d\\u0435\\u0435 \\u0437\\u0430\\u0434\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u043f\\u043e\\u0440\\u043e\\u0433\\u0430 \\u2014 \\u044d\\u0442\\u043e \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f (\\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u044e |\\u0394\\u03b1\\u0302|<0.15 \\u0438 \\u043e\\u0442\\u043d\\u043e\\u0441\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u0440\\u0430\\u0437\\u043d\\u0438\\u0446\\u0430 PR/srank <20% \\u043a\\u0430\\u043a \\u0447\\u0435\\u0440\\u043d\\u043e\\u0432\\u0438\\u043a).\\n\\n**\\u041a\\u0440\\u0438\\u0442\\u0438\\u0447\\u043d\\u043e \\u0443\\u0442\\u043e\\u0447\\u043d\\u0438\\u0442\\u044c \\u0443 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f (\\u0432 \\u0440\\u0430\\u043c\\u043a\\u0430\\u0445 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0430 6 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u043e\\u0432):** (a) \\u0432\\u0435\\u0440\\u043d\\u0430 \\u043b\\u0438 \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0432\\u043a\\u0430 BAdam; (b) \\u043f\\u0440\\u0438\\u0435\\u043c\\u043b\\u0435\\u043c \\u043b\\u0438 stdlib-Python/tiny-model \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b; (c) \\u043f\\u043e\\u0440\\u043e\\u0433 \\\"comparable\\\". \\u041f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u044e \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0430\\u043f\\u043f\\u0440\\u0443\\u0432\\u0430\\u043b\\u0430 \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441\\u0430.\", \"evidence\": \"\\u0418\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u044f: /workspace \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e task.json (699 \\u0431\\u0430\\u0439\\u0442) \\u0441 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u043e\\u043c \\u0438 context \\\"Design an experiment... Do not claim that an experiment was run\\\"; documents.track.md \\u0441\\u0441\\u044b\\u043b\\u0430\\u0435\\u0442\\u0441\\u044f \\u043d\\u0430 \\u0442\\u0435\\u043a\\u0441\\u0442 \\\"Design-only task; repositories and compute are not required\\\", \\u043d\\u043e \\u0444\\u0430\\u0439\\u043b track.md \\u0444\\u0438\\u0437\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 (find \\u043f\\u043e / \\u043d\\u0438\\u0447\\u0435\\u0433\\u043e \\u043d\\u0435 \\u043d\\u0430\\u0448\\u0451\\u043b). \\u0420\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u044f \\u043a\\u043e\\u0434\\u0430 BAdam, \\u0441\\u0442\\u0430\\u0442\\u0435\\u0439, \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u043e\\u0432, \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0435\\u0442. \\u0421\\u0440\\u0435\\u0434\\u0430: Python 3.14.4, numpy/scipy/torch/transformers \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442 (import \\u043f\\u0430\\u0434\\u0430\\u0435\\u0442), \\u0441\\u0435\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430, GPU \\u043d\\u0435\\u0442, 224 CPU, ~2 \\u0413\\u0411 RAM. \\u041e\\u0442\\u0441\\u044e\\u0434\\u0430: \\u043b\\u044e\\u0431\\u043e\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043e\\u0431\\u044f\\u0437\\u0430\\u043d \\u0431\\u044b\\u0442\\u044c \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c\\u044b\\u043c \\u043d\\u0430 stdlib-Python \\u0441 \\u043a\\u0440\\u043e\\u0448\\u0435\\u0447\\u043d\\u043e\\u0439 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c\\u044e \\u0438 \\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f\\u043c\\u0438 Adam/BAdam/Jacobi-SVD/ML-\\u043f\\u043e\\u0434\\u0433\\u043e\\u043d\\u043a\\u0438 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u0437\\u0430\\u043a\\u043e\\u043d\\u0430. \\u041f\\u043e\\u043d\\u044f\\u0442\\u0438\\u0439\\u043d\\u044b\\u0435 \\u043f\\u0440\\u0438\\u0432\\u044f\\u0437\\u043a\\u0438: heavy-tailed self-regularization \\u0438 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u044b\\u0435 \\u043f\\u043e\\u0434\\u0433\\u043e\\u043d\\u043a\\u0438 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430 \\u2014 Martin & Mahoney; participation ratio \\u2014 Roy & Vetterli; stable rank \\u2014 Rudelson & Vershynin; BAdam \\u2014 block-coordinate Adam, arXiv 2404.18182 (\\u043f\\u043e \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438; \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438 \\u043d\\u0435\\u0442 \\u2014 \\u0432\\u044b\\u043d\\u0435\\u0441\\u0435\\u043d\\u043e \\u0432 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f).\", \"stage\": \"plan\", \"assumptions\": [\"BAdam = block-coordinate Adam: \\u043e\\u0434\\u0438\\u043d \\u0432\\u0435\\u0441\\u043e\\u0432\\u043e\\u0439 \\u0431\\u043b\\u043e\\u043a \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f Adam'\\u043e\\u043c \\u0437\\u0430 \\u0448\\u0430\\u0433, \\u043e\\u0441\\u0442\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0437\\u0430\\u043c\\u043e\\u0440\\u043e\\u0436\\u0435\\u043d\\u044b, \\u0446\\u0438\\u043a\\u043b\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043e\\u0431\\u0445\\u043e\\u0434 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 (\\u043f\\u043e \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u043e\\u0431 arXiv 2404.18182; \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u0432 workspace \\u043d\\u0435\\u0442 \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438)\", \"'Learning perturbation' \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d \\u043a\\u0430\\u043a \\u0444\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0435\\u0441\\u043e\\u0432 \\u0394W (\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0442\\u0438\\u0432\\u043d\\u043e\\u0435 \\u0437\\u0430 \\u043e\\u043a\\u043d\\u043e), \\u0441 \\u043e\\u043f\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u044b\\u043c \\u0441\\u0440\\u0435\\u0437\\u043e\\u043c \\u043f\\u043e \\u043f\\u0441\\u0435\\u0432\\u0434\\u043e\\u0433\\u0440\\u0430\\u0434\\u0438\\u0435\\u043d\\u0442\\u0443 m\\u0302_t\", \"\\u0422\\u044f\\u0436\\u0451\\u043b\\u044b\\u0439 \\u0445\\u0432\\u043e\\u0441\\u0442 = \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u043d\\u043e\\u0439 \\u0437\\u0430\\u043a\\u043e\\u043d \\u03c3^(\\u2212\\u03b1) \\u043f\\u043e \\u0432\\u0435\\u0440\\u0445\\u043d\\u0435\\u0439 \\u0447\\u0430\\u0441\\u0442\\u0438 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430 \\u0394W \\u0441 ML-\\u043e\\u0446\\u0435\\u043d\\u043a\\u043e\\u0