b\\u0439 (\\u043c\\u043e\\u0451 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435) vs blockwise-\\u043f\\u0430\\u0440\\u0430\\u043b\\u043b\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 (Megatron-style) \\u2014 \\u043a\\u0440\\u0438\\u0442\\u0438\\u0447\\u043d\\u043e \\u043c\\u0435\\u043d\\u044f\\u0435\\u0442 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\", \"\\u041e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 'learning perturbation' \\u2014 \\u0394W vs \\u043f\\u0441\\u0435\\u0432\\u0434\\u043e\\u0433\\u0440\\u0430\\u0434\\u0438\\u0435\\u043d\\u0442/\\u043c\\u043e\\u043c\\u0435\\u043d\\u0442\\u044b vs \\u0438\\u043d\\u0430\\u044f \\u0442\\u0440\\u0430\\u043a\\u0442\\u043e\\u0432\\u043a\\u0430 \\u0438\\u0437 \\u043f\\u0435\\u0440\\u0432\\u043e\\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430\", \"\\u041f\\u0440\\u0438\\u0435\\u043c\\u043b\\u0435\\u043c \\u043b\\u0438 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u043d\\u0430 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c Python \\u0441 \\u043a\\u0440\\u043e\\u0448\\u0435\\u0447\\u043d\\u043e\\u0439 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c\\u044e (\\u043d\\u0435\\u0442 numpy/torch, \\u043d\\u0435\\u0442 \\u0441\\u0435\\u0442\\u0438, 2 \\u0413\\u0411 RAM) \\u043a\\u0430\\u043a \\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0434\\u043b\\u044f \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430 \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\", \"\\u0421\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u043c\\u043e\\u0435 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0449\\u0435\\u0433\\u043e track.md \\u2014 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u044b\\u0435 \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u043a \\u0444\\u043e\\u0440\\u043c\\u0430\\u0442\\u0443/\\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0443 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 \\u04