u0435\\u043d\\u0438\\u0435 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u043e\\u0432 \\u2014 \\u043d\\u0435 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 sample-efficiency. Loss-\\u043a\\u0440\\u0438\\u0432\\u044b\\u0435 \\u043b\\u043e\\u0433\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442, \\u043d\\u043e \\u043d\\u0435 \\u0432\\u0445\\u043e\\u0434\\u044f\\u0442 \\u0432 decision rule.\\n7. **[\\u041e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435]** \\u0420\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b \\u043c\\u043e\\u0433\\u0443\\u0442 \\u043e\\u0442\\u043b\\u0438\\u0447\\u0430\\u0442\\u044c\\u0441\\u044f \\u043f\\u0440\\u0438 finetune \\u0441 weight decay >0, warmup \\u0438\\u043b\\u0438 \\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0432\\u043d\\u043e\\u0439 \\u0441\\u0445\\u0435\\u043c\\u0435 \\u043e\\u0431\\u0445\\u043e\\u0434\\u0430 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u2014 \\u0432\\u043d\\u0435 \\u0441\\u043a\\u043e\\u0443\\u043f\\u0430.\\n8. **[\\u0424\\u0430\\u043a\\u0442 \\u043e \\u0441\\u0440\\u0435\\u0434\\u0435]** track.md \\u0443\\u043f\\u043e\\u043c\\u044f\\u043d\\u0443\\u0442 \\u0432 task.json, \\u043d\\u043e \\u0444\\u0430\\u0439\\u043b \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442; Jacobi-SVD \\u0437\\u0430\\u043c\\u0435\\u0440\\u0435\\u043d: 0.07 \\u0441 (32\\u00d732), 0.6 \\u0441 (64\\u00d764) \\u0432 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c Python.\\n\\n## \\u0427\\u0435\\u043a-\\u043b\\u0438\\u0441\\u0442 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f (\\u043d\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u0432 \\u0440\\u0430\\u043c\\u043a\\u0430\\u0445 \\u044d\\u0442\\u043e\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430)\\n1. \\u0420\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f: \\u043c\\u0430\\u0442\\u043c\\u043e\\u0434\\u0443\\u043b\\u044c, \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440, Adam/BAdam/SGD, Jacobi-SVD, CLAUSET-\\u043f\\u043e\\u0434\\u0433\\u043e\\u043d\\u043a\\u0430, PR/srank.\\n2. Positive/null controls \\u2192 \\u0432\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043c\\u0435\\u043d\\u0442\\u0430.\\n3. \\u0421\\u0435\\u0442\\u043a\\u0430 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 (45\\u201360), \\u043b\\u043e\\u0433\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u043e\\u0432 per (module, window, run).\\n4. \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437: TOST + CI-\\u043f\\u0435\\u0440\\u0435\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 + sensitivity \\u043f\\u043e\\u0440\\u043e\\u0433\\u043e\\u0432 + \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u044b + \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u2016\\u0394W\\u2016_F.\\n5. \\u041e\\u0442\\u0447\\u0451\\u0442: \\u043f\\u043e-\\u043c\\u043e\\u0434\\u0443\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0432\\u044b\\u0432\\u043e\\u0434\\u044b \\u0441 \\u044f\\u0432\\u043d\\u043e \\u043f\\u043e\\u043c\\u0435\\u0447\\u0435\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f\\u043c\\u0438.\", \"evidence\": \"\\u0418\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u044f \\u0441\\u0440\\u0435\\u0434\\u044b (\\u043e\\u0431\\u044a\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u044f): /workspace \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e task.json; track.md \\u0443\\u043f\\u043e\\u043c\\u044f\\u043d\\u0443\\u0442 \\u0432 documents, \\u043d\\u043e \\u0444\\u0430\\u0439\\u043b \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043e find \\u043f\\u043e /). numpy/scipy/torch \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442 (import \\u043f\\u0430\\u0434\\u0430\\u0435\\u0442), \\u0441\\u0435\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430, GPU \\u043d\\u0435\\u0442, 224 CPU, ~2 \\u0413\\u0411 RAM, Python 3.14.4. \\u0412\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u043d\\u0430\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 feasibility (\\u043d\\u0435 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442, \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0442\\u0430\\u0439\\u043c\\u0438\\u043d\\u0433 \\u0443\\u0442\\u0438\\u043b\\u0438\\u0442\\u044b): \\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0430\\u044f \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f one-sided Jacobi SVD \\u0432 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c Python \\u0441\\u043e\\u0448\\u043b\\u0430\\u0441\\u044c \\u043d\\u0430 \\u0433\\u0430\\u0443\\u0441\\u0441\\u043e\\u0432\\u044b\\u0445 \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446\\u0430\\u0445; \\u0437\\u0430\\u043c\\u0435\\u0440\\u0435\\u043d\\u043e 0.07 \\u0441 \\u0434\\u043b\\u044f 32\\u00d732 \\u0438 0.6 \\u0441 \\u0434\\u043b\\u044f 64\\u00d764 \\u2014 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0430\\u0435\\u0442 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c\\u043e\\u0441\\u0442\\u044c \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0430 \\u043d\\u0430 stdlib-Python (\\u22489600 SVD \\u2248 11\\u201312 \\u043c\\u0438\\u043d). \\u0414\\u0438\\u0437\\u0430\\u0439\\u043d \\u043e\\u043f\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u0